#!/usr/bin/env node
/**
 * Generate `CHANGELOG.md` from the commit history on a branch.
 *
 * ## Why this is a script and not a written file
 *
 * A hand-written changelog is correct on the day it is written and wrong
 * the next morning. This one is regenerated by CI or by hand, so the only
 * way it can be stale is if nobody runs it — which is visible in the diff.
 *
 * ## Why there is no `## [0.1.0]` heading yet
 *
 * The repository has never cut a version tag: its only tag is
 * `archive/2026-08-26-pre-mvp-simplify`, which marks a point in history
 * rather than a release. The version in `Cargo.toml`,
 * `package.json` and `tauri.conf.json` is `0.1.0`, but nothing has been
 * published under it. A changelog that opened with a fabricated
 * "0.1.0 — 2026-10-06" would assert a release that did not happen.
 *
 * So the output is headed "Unreleased", and becomes a versioned section
 * the first time a `v*` tag is cut. The `## [Unreleased]` heading is kept
 * even then, because squash merges keep landing after any given tag.
 *
 * ## Grouping
 *
 * Conventional-Commit prefixes decide the section, because the repository
 * already uses them consistently:
 *
 *   fix   → Fixed
 *   feat  → Added
 *   docs  → Documentation
 *   chore → Maintenance
 *
 * Anything else lands under "Other" rather than being dropped, so a
 * malformed subject is visible instead of silently missing.
 */
import { execFileSync } from 'node:child_process';
import { existsSync, writeFileSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

// This file lives in `<repo>/scripts/`, so the repository root is one level
// up — not two. Getting this wrong writes the changelog *outside* the repo
// while still reporting success, so the path is resolved once, here, and
// asserted below.
const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const BRANCH = process.argv[2] ?? 'dev';
const OUT = resolve(repoRoot, 'CHANGELOG.md');

/** `{ type, scope, subject, sha, pr, body }` per commit, oldest first. */
function commits() {
  const raw = execFileSync(
    'git',
    ['log', '--reverse', '--no-merges', '--format=%H%x1f%s%x1f%b%x1e', BRANCH],
    { cwd: repoRoot, encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 }
  );

  return raw
    .split('\x1e')
    .map((r) => r.trim())
    .filter((r) => r.length > 0)
    .map((record) => {
      const [sha, subject, body = ''] = record.split('\x1f');
      const m = /^(\w+)(?:\(([^)]+)\))?(?:\!)?:\s*(.*)$/.exec(subject);
      return {
        sha,
        type: m ? m[1].toLowerCase() : 'other',
        scope: m ? (m[2] ?? '') : '',
        subject: m ? m[3] : subject,
        pr: /#(\d+)\s*$/.exec(body) ?? /#(\d+)\s*$/.exec(subject),
        body,
      };
    });
}

/**
 * Section order is the order a reader wants, not the order the prefixes
 * appear in history.
 *
 * `[FACT]` The `other` bucket is a *catch-all*, not a "no prefix" bucket.
 * An earlier version listed only feat/fix/docs/chore and fell through to
 * `other` only when the subject failed to parse — so every commit typed
 * `test:`, `ci:`, `style:`, `build:`, `tools:` or `archive:` was parsed
 * correctly, matched no section, and was silently dropped. Measured: 191
 * non-merge commits, 156 bullets, 35 missing. The file even claimed
 * "anything else lands under Other rather than being dropped".
 */
const SECTIONS = [
  { keys: ['feat'], title: 'Added' },
  { keys: ['fix'], title: 'Fixed' },
  { keys: ['perf', 'refactor'], title: 'Changed' },
  { keys: ['test', 'ci', 'build', 'style', 'tools', 'archive'], title: 'Build and tooling' },
  { keys: ['docs'], title: 'Documentation' },
  { keys: ['chore', 'revert'], title: 'Maintenance' },
  { keys: null, title: 'Other' },
];

function sectionFor(type) {
  return SECTIONS.find((s) => s.keys !== null && s.keys.includes(type));
}

function render() {
  const all = commits();
  if (all.length === 0) throw new Error(`no commits found on ${BRANCH}`);

  const out = [
    '# Changelog',
    '',
    '<!--',
    '  GENERATED FILE — do not edit by hand.',
    '',
    '  Regenerate with:  node scripts/generate-changelog.mjs dev',
    '',
    '  The project has not cut a version tag yet, so everything lives under',
    '  "Unreleased". When the first `v*` tag is cut, move the commits above',
    '  that tag into a `## [x.y.z] — date` section.',
    '-->',
    '',
    'All notable changes to this project are recorded here.',
    '',
    '## [Unreleased]',
    '',
  ];

  let rendered = 0;
  for (const { keys, title } of SECTIONS) {
    const group = keys === null
      ? all.filter((c) => sectionFor(c.type) === undefined)
      : all.filter((c) => keys.includes(c.type));
    if (group.length === 0) continue;
    out.push(`### ${title}`, '');
    for (const c of group) {
      const scope = c.scope ? `**${c.scope}**: ` : '';
      const pr = c.pr ? ` (#${c.pr[1]})` : '';
      out.push(`- ${scope}${c.subject}${pr} (${c.sha.slice(0, 7)})`);
    }
    out.push('');
    rendered += group.length;
  }

  // The invariant this script exists to keep: every commit reachable from
  // the branch appears exactly once. Without it, a prefix added to the
  // conventional-commit vocabulary silently deletes history from the
  // changelog, which is the one failure a changelog cannot be allowed to
  // have. It has already caught two real defects: prefixes parsed but
  // mapped to no section (35 commits), and a catch-all that could never
  // match (14 commits).
  //
  // What it does NOT catch, measured: removing `test` from its section
  // moves those 16 commits into "Other" and this check still passes,
  // because nothing is lost — only misfiled. The catch-all is doing its
  // job too well to be a mistake-detector. Grouping changes therefore
  // need a human reading the diff, not a green run.
  if (rendered !== all.length) {
    throw new Error(
      `dropped ${all.length - rendered} of ${all.length} commits — a type has no section`
    );
  }

  return { text: out.join('\n'), count: all.length };
}

const { text, count } = render();

// Fail loudly if the resolved root is not actually the repository. The
// first version of this script resolved two levels up and wrote the
// changelog to a sibling of the worktree while printing a success message,
// because every assertion it did make (git log, rendering, write) passed.
if (!existsSync(resolve(repoRoot, '.git'))) {
  throw new Error(`repoRoot does not look like a repository: ${repoRoot}`);
}

writeFileSync(OUT, text, 'utf8');
console.log(`wrote ${OUT} from ${count} commits on ${BRANCH}`);
